//! Parity tests for serialization helpers (`tests/fixtures/serialize.json`, generated by
//! `tests/fixtures/gen_serialize.py`).

mod common;

use common::{cases, compare_values, decode, encode, load_fixture};
use meerschaum_kernel::cast;
use meerschaum_kernel::dtypes::Srid;
use meerschaum_kernel::frame::{Column, Frame};
use meerschaum_kernel::geometry::{self, Geometry};
use meerschaum_kernel::serialize::{self, GeometryFormat, GeometryOutput};
use meerschaum_kernel::value::Value;
use polars::prelude::NamedFrom;
use serde_json::{Value as J, json};

fn bytes_hex(b: &[u8]) -> J {
    json!({"t": "bytes_hex", "v": hex::encode(b)})
}

fn check(case: &J, result: Result<J, String>, failures: &mut Vec<String>) {
    match (case.get("ok"), result) {
        (Some(expected), Ok(actual)) => {
            let ok = match (expected, &actual) {
                (J::Object(e), J::Object(a))
                    if e.get("t") == Some(&json!("bytes_hex"))
                        && a.get("t") == Some(&json!("bytes_hex")) =>
                {
                    e["v"]
                        .as_str()
                        .unwrap()
                        .eq_ignore_ascii_case(a["v"].as_str().unwrap())
                }
                (J::String(e), J::String(a)) => e == a,
                _ => compare_values(expected, &actual).is_ok() || *expected == actual,
            };
            if !ok {
                failures.push(format!("{case}\n    got {actual}"));
            }
        }
        (None, Err(_)) => {}
        (Some(_), Err(e)) => failures.push(format!("{case}\n    unexpected error {e}")),
        (None, Ok(v)) => failures.push(format!("{case}\n    expected error, got {v}")),
    }
}

fn geometry_output(out: Option<GeometryOutput>) -> J {
    match out {
        None => J::Null,
        Some(GeometryOutput::Text(s)) => J::String(s),
        Some(GeometryOutput::Bytes(b)) => bytes_hex(&b),
        Some(GeometryOutput::GeoJson(j)) => json!({"t": "json", "v": j}),
    }
}

#[test]
fn serialize_parity() {
    let fixture = load_fixture("serialize");
    let mut failures = Vec::new();
    let mut checked = 0usize;
    for case in cases(&fixture) {
        let f = case["fn"].as_str().unwrap();
        let args = case["args"].as_array().unwrap();
        let arg0 = decode(&args[0]);
        let passthrough = |r: Result<Option<String>, serialize::SerializeError>, v: &Value| {
            r.map(|o| o.map(J::String).unwrap_or_else(|| encode(v)))
                .map_err(|e| e.to_string())
        };
        checked += 1;
        match f {
            "serialize_bytes" => check(
                case,
                passthrough(serialize::serialize_bytes(&arg0), &arg0),
                &mut failures,
            ),
            "encode_bytes_for_bytea" | "encode_bytes_for_bytea_noprefix" => check(
                case,
                passthrough(
                    serialize::encode_bytes_for_bytea(&arg0, f == "encode_bytes_for_bytea"),
                    &arg0,
                ),
                &mut failures,
            ),
            "deserialize_bytes_string" | "deserialize_bytes_string_hex" => {
                let result = match &arg0 {
                    Value::Str(s) => serialize::deserialize_bytes_string(s, f.ends_with("hex"))
                        .map(|b| bytes_hex(&b))
                        .map_err(|e| e.to_string()),
                    other => Ok(encode(other)),
                };
                check(case, result, &mut failures);
            }
            "serialize_datetime" => {
                let Value::Datetime(dt) = &arg0 else { panic!() };
                check(
                    case,
                    Ok(J::String(serialize::serialize_datetime(dt))),
                    &mut failures,
                );
            }
            "serialize_date" => {
                let result = match &arg0 {
                    Value::Date(d) => J::String(serialize::serialize_date(d)),
                    _ => J::Null,
                };
                check(case, Ok(result), &mut failures);
            }
            "json_serialize_value" => {
                check(
                    case,
                    Ok(serialize::json_serialize_value(&arg0)),
                    &mut failures,
                );
            }
            "serialize_geometry" => {
                let fmt = GeometryFormat::parse(args[1].as_str().unwrap());
                let srid = args[2].as_i64();
                let result = serialize::serialize_geometry(&arg0, fmt, srid)
                    .map(geometry_output)
                    .map_err(|e| e.to_string());
                check(case, result, &mut failures);
            }
            "serialize_geometry_with_srid" => {
                let Value::Geometry(mut g) = arg0.clone() else {
                    panic!()
                };
                g.srid = Some(args[1].as_i64().unwrap() as i32);
                let result = serialize::serialize_geometry(
                    &Value::Geometry(g),
                    GeometryFormat::WkbHex,
                    None,
                )
                .map(geometry_output)
                .map_err(|e| e.to_string());
                check(case, result, &mut failures);
            }
            "geometry_is_wkt" => {
                let got = cast::geometry_is_wkt(&arg0);
                check(case, Ok(got.map(J::Bool).unwrap_or(J::Null)), &mut failures);
            }
            "geometry_is_gpkg" => {
                let got = matches!(&arg0, Value::Bytes(b) if geometry::geometry_is_gpkg(b));
                check(case, Ok(J::Bool(got)), &mut failures);
            }
            "gpkg_wkb_to_wkb" => {
                let Value::Bytes(b) = &arg0 else { panic!() };
                let result = geometry::gpkg_wkb_to_wkb(b)
                    .map(|(wkb, srid, flags)| json!([bytes_hex(&wkb), {"t": "int", "v": srid}, {"t": "int", "v": flags}]))
                    .map_err(|e| e.to_string());
                match (&result, case.get("ok")) {
                    (Ok(J::Array(a)), Some(J::Array(e))) => {
                        let ok = a[0]["v"]
                            .as_str()
                            .unwrap()
                            .eq_ignore_ascii_case(e[0]["v"].as_str().unwrap())
                            && a[1] == e[1]
                            && a[2] == e[2];
                        if !ok {
                            failures.push(format!("{case}\n    got {result:?}"));
                        }
                    }
                    _ => failures.push(format!("{case}\n    got {result:?}")),
                }
            }
            "attempt_cast_to_geometry" => {
                let got = cast::attempt_cast_to_geometry(&arg0);
                let actual = match &got {
                    Value::Bytes(b) => bytes_hex(b),
                    other => encode(other),
                };
                check(case, Ok(actual), &mut failures);
            }
            "deserialize_geometry" => {
                let result = serialize::deserialize_geometry(&arg0)
                    .map(|g| encode(&Value::Geometry(g)))
                    .map_err(|e| e.to_string());
                check(case, result, &mut failures);
            }
            "to_polars_geoarrow" => {
                let srid = match &arg0 {
                    Value::Int(i) => Srid::Code(*i),
                    Value::Str(s) => Srid::Authority(s.clone()),
                    _ => panic!(),
                };
                let mut geom_col = Column::object(
                    "geom",
                    vec![
                        Value::Geometry(Geometry::from_wkt("POINT (1 2)").unwrap()),
                        Value::Null,
                    ],
                );
                geom_col.crs = Some(srid);
                let meta = Column::object(
                    "meta",
                    vec![Value::Json(json!({"b": 1, "a": 2})), Value::Null],
                );
                let id = Column::native(polars::prelude::Series::new("id".into(), [1i64, 2]));
                let frame = Frame::new(vec![id, geom_col, meta]).unwrap();
                let batch = frame.to_record_batch().unwrap();
                let ok = &case["ok"];
                for name in ["geom", "meta"] {
                    let field = batch.schema().field_with_name(name).unwrap().clone();
                    let md = field.metadata();
                    let expected_ext = ok["fields"][name]["extension"].as_str().unwrap();
                    if md.get("ARROW:extension:name").map(String::as_str) != Some(expected_ext) {
                        failures.push(format!("{case}\n    {name}: extension {md:?}"));
                    }
                    let polars_dtype = ok["fields"][name]["polars_dtype"].as_str().unwrap();
                    // Extension('geoarrow.wkb', Binary, '<metadata>')
                    let expected_md = polars_dtype
                        .rsplit_once(", '")
                        .map(|(_, r)| r.trim_end_matches("')"))
                        .unwrap_or("");
                    if md
                        .get("ARROW:extension:metadata")
                        .map(String::as_str)
                        .unwrap_or("")
                        != expected_md
                    {
                        failures.push(format!(
                            "{case}\n    {name}: metadata {md:?} != {expected_md}"
                        ));
                    }
                }
                let geom = batch.column_by_name("geom").unwrap();
                let geom = arrow::compute::cast(geom, &arrow::datatypes::DataType::Binary).unwrap();
                let geom = geom
                    .as_any()
                    .downcast_ref::<arrow::array::BinaryArray>()
                    .unwrap();
                let expected_hex = ok["geom_wkb_hex"][0].as_str().unwrap();
                if hex::encode(geom.value(0)) != expected_hex {
                    failures.push(format!("{case}\n    wkb {}", hex::encode(geom.value(0))));
                }
                let meta = batch.column_by_name("meta").unwrap();
                let meta = arrow::compute::cast(meta, &arrow::datatypes::DataType::Utf8).unwrap();
                let meta = meta
                    .as_any()
                    .downcast_ref::<arrow::array::StringArray>()
                    .unwrap();
                if meta.value(0) != ok["meta"][0].as_str().unwrap() {
                    failures.push(format!("{case}\n    meta {}", meta.value(0)));
                }
                // Round trip back into a kernel frame.
                let back = Frame::from_record_batch(&batch).unwrap();
                let gcol = back.column("geom").unwrap();
                assert!(matches!(gcol.data.get(0), Value::Geometry(_)));
                let expected_crs = ok["fields"]["geom"]["ext_metadata"]
                    .as_str()
                    .and_then(|s| serde_json::from_str::<J>(s).ok())
                    .and_then(|j| j.get("crs").and_then(|c| c.as_str().map(str::to_string)));
                if gcol.crs.as_ref().and_then(Srid::to_crs) != expected_crs {
                    failures.push(format!("{case}\n    round-trip crs {:?}", gcol.crs));
                }
                assert!(matches!(
                    back.column("meta").unwrap().data.get(0),
                    Value::Json(_)
                ));
            }
            "to_json" => {
                // `meerschaum.utils.dataframe.to_json` is not part of the kernel port (see README).
                checked -= 1;
            }
            other => panic!("unhandled fixture function {other}"),
        }
    }
    assert!(checked > 400, "too few cases checked: {checked}");
    if !failures.is_empty() {
        panic!(
            "{} serialize parity failures:\n{}",
            failures.len(),
            failures.join("\n")
        );
    }
}
